# MobileCoreError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class MobileCoreError(Exception):
    pass

_UniffiTempMobileCoreError = MobileCoreError

class MobileCoreError:  # type: ignore
    
    class Failed(_UniffiTempMobileCoreError):
        
        def __init__(self, code, domain, operation, detail):
            super().__init__(", ".join([
                "code={!r}".format(code),
                "domain={!r}".format(domain),
                "operation={!r}".format(operation),
                "detail={!r}".format(detail),
            ]))
            self.code = code
            self.domain = domain
            self.operation = operation
            self.detail = detail

        def __repr__(self):
            return "MobileCoreError.Failed({})".format(str(self))
    _UniffiTempMobileCoreError.Failed = Failed # type: ignore

MobileCoreError = _UniffiTempMobileCoreError # type: ignore
del _UniffiTempMobileCoreError


class _UniffiFfiConverterTypeMobileCoreError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return MobileCoreError.Failed(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterOptionalString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, MobileCoreError.Failed):
            _UniffiFfiConverterString.check_lower(value.code)
            _UniffiFfiConverterString.check_lower(value.domain)
            _UniffiFfiConverterString.check_lower(value.operation)
            _UniffiFfiConverterOptionalString.check_lower(value.detail)
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, MobileCoreError.Failed):
            buf.write_i32(1)
            _UniffiFfiConverterString.write(value.code, buf)
            _UniffiFfiConverterString.write(value.domain, buf)
            _UniffiFfiConverterString.write(value.operation, buf)
            _UniffiFfiConverterOptionalString.write(value.detail, buf)

